import{_ as e,c as s,o as a,a3 as o}from"./chunks/framework.Dokpd4od.js";const p=JSON.parse('{"title":"Customers","description":"","frontmatter":{},"headers":[],"relativePath":"master/website/customers/index.md","filePath":"master/website/customers/index.md","lastUpdated":1792041590000}'),n={name:"master/website/customers/index.md"};function r(i,t,c,d,l,h){return a(),s("div",null,t[0]||(t[0]=[o(`<h1 id="customers" tabindex="-1">Customers <a class="header-anchor" href="#customers" aria-label="Permalink to &quot;Customers&quot;">​</a></h1><p>Website customers are the people who use your public site. Each one is a record in the same contacts list that Contacts uses. The Website app does not keep a second list. It adds a place to see who can sign in, and a sign-in and register page for visitors.</p><blockquote><p><strong>In simple words:</strong> A website customer is a contact. Website only adds the sign-in part.</p></blockquote><p>Open <code>Website → Customers</code>.</p><h2 id="website-accounts-and-contacts" tabindex="-1">Website accounts and Contacts <a class="header-anchor" href="#website-accounts-and-contacts" aria-label="Permalink to &quot;Website accounts and Contacts&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Question</th><th>Answer</th></tr></thead><tbody><tr><td>Where is the data stored?</td><td>In the contact records, shared with Contacts, Sales, Purchase and Invoices.</td></tr><tr><td>What happens if I edit a customer here?</td><td>The change shows in Contacts and everywhere else.</td></tr><tr><td>What does Website add?</td><td>The <strong>Portal Access</strong> badge and filter, the <strong>Customer Portal</strong> section, and the public <strong>Register</strong> and <strong>Login</strong> pages.</td></tr><tr><td>Who can sign in?</td><td>Only contacts with portal access.</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Portal actions need the customer portal, which comes with the <strong>Website</strong> plugin. If you do not see the <strong>Portal Access</strong> button, check that the plugin is installed.</p></div><h2 id="how-a-customer-gets-an-account" tabindex="-1">How a customer gets an account <a class="header-anchor" href="#how-a-customer-gets-an-account" aria-label="Permalink to &quot;How a customer gets an account&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Visitor registers on /register  →  contact is created  →  Portal Access: Granted</span></span>
<span class="line"><span>Admin creates a contact         →  Portal Access: Not Granted  →  Admin grants access  →  Granted</span></span></code></pre></div><ul><li>A visitor who registers on the public site becomes a contact and shows as <strong>Granted</strong>.</li><li>A contact you create in the admin panel cannot sign in until you grant portal access.</li></ul><h2 id="in-this-section" tabindex="-1">In this section <a class="header-anchor" href="#in-this-section" aria-label="Permalink to &quot;In this section&quot;">​</a></h2><ul><li><a href="./customers.html">Website customers</a>: the list, tabs, the <strong>Portal Access</strong> badge and filter, the form and the sub pages.</li><li><a href="./portal-and-sign-in.html">Portal and sign-in</a>: what visitors see on <strong>Register</strong>, <strong>Login</strong> and password pages, and how you manage access.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../../getting-started/contacts/contacts.html">Contacts</a></li><li><a href="./../../general-settings/users/portal-access.html">Portal access</a></li><li><a href="./../">Website overview</a></li></ul>`,14)]))}const g=e(n,[["render",r]]);export{p as __pageData,g as default};
